CREATE TABLE products (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), sku text NOT NULL, name text NOT NULL, description text, price bigint NOT NULL CHECK (price >= 0), currency text NOT NULL DEFAULT 'BRL' CHECK (currency IN ('BRL','USD')), unit text NOT NULL DEFAULT 'un', stock integer CHECK (stock IS NULL OR stock >= 0), active boolean NOT NULL DEFAULT true, tags jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE UNIQUE INDEX products_org_sku_idx ON products (org_id, sku); CREATE INDEX products_org_name_idx ON products (org_id, name); ALTER TABLE products ENABLE ROW LEVEL SECURITY; CREATE POLICY products_isolation_by_org ON products FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
CREATE TABLE product_variants (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, sku text NOT NULL, name text NOT NULL, price_adjustment bigint NOT NULL DEFAULT 0, stock integer CHECK (stock IS NULL OR stock >= 0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX product_variants_org_sku_idx ON product_variants (org_id, sku); CREATE INDEX product_variants_product_idx ON product_variants (product_id); ALTER TABLE product_variants ENABLE ROW LEVEL SECURITY; CREATE POLICY product_variants_isolation_by_org ON product_variants FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
CREATE TABLE discount_rules (id uuid PRIMARY KEY, org_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, type text NOT NULL CHECK (type IN ('percentage','fixed_amount')), value bigint NOT NULL CHECK (value >= 0), minimum_subtotal bigint NOT NULL DEFAULT 0 CHECK (minimum_subtotal >= 0), starts_at timestamptz, ends_at timestamptz, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (type <> 'percentage' OR value <= 10000), CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at));
CREATE INDEX discount_rules_org_active_idx ON discount_rules (org_id, active); ALTER TABLE discount_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY discount_rules_isolation_by_org ON discount_rules FOR ALL TO app_user USING (org_id = current_setting('app.current_org_id', true)::uuid);
GRANT SELECT, INSERT, UPDATE, DELETE ON products, product_variants, discount_rules TO app_user;
ALTER PUBLICATION electric_publication_default ADD TABLE products, product_variants, discount_rules;
UPDATE permission_groups SET capabilities = capabilities || '["catalog:read", "catalog:write"]'::jsonb, updated_at = now() WHERE name IN ('Proprietário','Administrador','Gerente') AND NOT capabilities @> '["catalog:read", "catalog:write"]'::jsonb;
UPDATE permission_groups SET capabilities = capabilities || '["catalog:read"]'::jsonb, updated_at = now() WHERE name IN ('Agente','Visualizador') AND NOT capabilities @> '["catalog:read"]'::jsonb;
